        public const string ExtraLocked = "Недоступно с выбранным оружием. Пулемётчик и снайпер несут оружие и его боезапас; дымы и ручные гранаты доступны.";
        public static string Ammo(int weapon, int rig)
        {
            int magazine = weapon == 1 ? 100 : weapon == 4 ? 10 : 30, reserve = weapon == 1 ? (rig + 1) * 100 : weapon == 4 ? 30 + rig * 20 : 90 + rig * 60;
            return magazine + " / " + reserve + " патронов (всего " + (magazine + reserve) + ")";
        }

        public static string TrainingEffect(int kind, int level)
        {
            if (kind == 4)
                return "Освоено уровней навыков: " + level;
            if (kind == 3)
                return level == 0 ? "Базовая точность" : "Вероятность попадания +" + (level * 5) + "%";
            if (kind == 0)
                return level == 0 ? "Обычная скорость" : "Перезарядка быстрее на " + (level * 5) + "%";
            if (kind == 1)
                return "Жгут: " + (3 - level * .2).ToString("0.0", System.Globalization.CultureInfo.GetCultureInfo("ru-RU")) + " с";
            return level == 0 ? "Обычное восстановление" : "Максимум +" + (level * 5) + " · восстановление +" + level + " ед./с · блок −" + (level * .5f).ToString("0.0", System.Globalization.CultureInfo.GetCultureInfo("ru-RU")) + " с";
        }
